import numpy as np
def controlled(U): U = np.asarray(U, dtype=complex) P0 = np.array([[1, 0], [0, 0]], dtype=complex) P1 = np.array([[0, 0], [0, 1]], dtype=complex) return np.kron(P0, np.eye(2, dtype=complex)) + np.kron(P1, U)
def cnot_from_cz(): H = np.array([[1, 1], [1, -1]], dtype=complex) / np.sqrt(2) Z = np.array([[1, 0], [0, -1]], dtype=complex) CZ = controlled(Z) IH = np.kron(np.eye(2, dtype=complex), H) return IH @ CZ @ IH

